/* @autogenerated */
import { provideHttpClient } from '@angular/common/http';
import { provideHttpClientTesting } from '@angular/common/http/testing';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { MatDialog } from '@angular/material/dialog';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { Subject, config, of, throwError } from 'rxjs';
import { Logger } from '@shared/context/observability/logger.service';
import { DownloadBlob, UploadProgress } from '@shared/data/repository/provider/repository-provider.interface';
import { EditableUploadComponent } from './editable-upload.component';

describe('EditableUploadComponent', () => {
  let fixture: ComponentFixture<EditableUploadComponent>;
  let component: EditableUploadComponent;
  let dialog: { open: jasmine.Spy };
  let dialogRef: { close: jasmine.Spy };
  let logger: jasmine.SpyObj<Logger>;
  let uploads: Subject<UploadProgress>;
  let upload: jasmine.Spy;
  let download: jasmine.Spy;

  const progress = (percent: number, data?: string) =>
    Object.assign(new UploadProgress(), { progressPercent: percent, data });
  const file = (name: string, type: string) => new File(['content'], name, { type });

  beforeEach(() => {
    dialogRef = { close: jasmine.createSpy('close') };
    dialog = { open: jasmine.createSpy('open').and.returnValue(dialogRef) };
    logger = jasmine.createSpyObj<Logger>('Logger', ['error']);
    uploads = new Subject<UploadProgress>();
    upload = jasmine.createSpy('upload').and.returnValue(uploads);
    download = jasmine.createSpy('download');
    TestBed.configureTestingModule({
      imports: [EditableUploadComponent, TranslocoTestingModule.forRoot({ langs: { en: {} } })],
      providers: [
        provideHttpClient(),
        provideHttpClientTesting(),
        { provide: MatDialog, useValue: dialog },
        { provide: Logger, useValue: logger },
      ],
    });
    // El componente importa MatDialogModule: su MatDialog se sustituye también
    TestBed.overrideProvider(MatDialog, { useValue: dialog });
    // Solo la plantilla del diálogo: la lógica se prueba sin el resto de la vista
    TestBed.overrideTemplate(EditableUploadComponent, '<ng-template #fileDialog></ng-template>');
    fixture = TestBed.createComponent(EditableUploadComponent);
    fixture.componentRef.setInput('upload', upload);
    fixture.componentRef.setInput('download', download);
    component = fixture.componentInstance;
    fixture.detectChanges();
  });

  afterEach(() => TestBed.resetTestingModule());

  it('uploads the chosen file showing its progress until the server answers', () => {
    component.showPreviewImage({ target: { files: [file('doc.pdf', 'application/pdf')] } });

    expect(component.uploadState()).toBe('uploading');
    expect(component.selectedFileName).toBe('doc.pdf');
    uploads.next(progress(40));
    expect(component.progressValue()).toBe(40);

    uploads.next(progress(100, 'tmp/doc.pdf'));

    expect(component.uploadState()).toBe('complete');
    expect(component.response()).toBe('tmp/doc.pdf');
    expect(component.filePreviewUrl).toBeNull();
  });

  it('previews the uploaded images', () => {
    component.uploadFile(file('photo.png', 'image/png'));
    uploads.next(progress(100, 'tmp/photo.png'));

    expect(component.isImageFile).toBeTrue();
    expect(component.filePreviewUrl).toMatch(/^blob:/);
  });

  it('logs a failed upload and lets the error through', async () => {
    upload.and.returnValue(throwError(() => new Error('boom')));
    const unhandled = jasmine.createSpy('onUnhandledError');
    const previous = config.onUnhandledError;
    // rxjs avisa del error sin manejar en un setTimeout
    config.onUnhandledError = unhandled;
    try {
      component.uploadFile(file('doc.pdf', 'application/pdf'));
      await new Promise((resolve) => setTimeout(resolve));
    } finally {
      config.onUnhandledError = previous;
    }

    expect(logger.error).toHaveBeenCalledWith('Upload failed', jasmine.any(Error));
    expect(unhandled).toHaveBeenCalledWith(jasmine.objectContaining({ message: 'boom' }));
  });

  it('ignores an empty selection', () => {
    component.showPreviewImage({ target: { files: [] } });

    expect(upload).not.toHaveBeenCalled();
  });

  it('uploads the first file dropped on it', () => {
    const event = { preventDefault: jasmine.createSpy(), stopPropagation: jasmine.createSpy() } as any;
    component.onDragOver(event);
    expect(component.isDragOver).toBeTrue();
    component.onDragLeave(event);
    expect(component.isDragOver).toBeFalse();

    component.onDrop({ ...event, dataTransfer: { files: [file('a.txt', 'text/plain'), file('b.txt', 'text/plain')] } });

    expect(upload).toHaveBeenCalledOnceWith(jasmine.objectContaining({ name: 'a.txt' }));
    component.onDrop({ ...event, dataTransfer: { files: [] } });
    expect(upload).toHaveBeenCalledTimes(1);
  });

  it('discards the upload to choose another file', () => {
    component.uploadFile(file('photo.png', 'image/png'));
    uploads.next(progress(100, 'tmp/photo.png'));

    component.discardAndChooseAnother();

    expect(component.uploadState()).toBe('select');
    expect(component.response()).toBeUndefined();
    expect(component.filePreviewUrl).toBeNull();
    expect(component.selectedFileName).toBeNull();
  });

  it('cancels an upload in progress', () => {
    component.uploadFile(file('doc.pdf', 'application/pdf'));

    component.cancelUpload();
    uploads.next(progress(100, 'late'));

    expect(component.uploadState()).toBe('select');
    expect(component.response()).toBeUndefined();
  });

  it('opens the file dialog and saves the chosen value', () => {
    const changes: unknown[] = [];
    component.registerOnChange((value: unknown) => changes.push(value));

    component.selectFile();
    component.save('tmp/doc.pdf');

    expect(dialog.open).toHaveBeenCalled();
    expect(dialogRef.close).toHaveBeenCalled();
    expect(changes).toEqual(['tmp/doc.pdf']);
  });

  it('opens the browser of files from its button', () => {
    const event = { preventDefault: jasmine.createSpy() };
    const button = { click: jasmine.createSpy() };

    component.openFileBrowser(event, button);

    expect(event.preventDefault).toHaveBeenCalled();
    expect(button.click).toHaveBeenCalled();
  });

  it('downloads the current file with its name', () => {
    component.writeValue('files/doc.pdf');
    const blob: DownloadBlob = { name: 'doc.pdf', data: new Blob(['x']) } as DownloadBlob;
    download.and.returnValue(of(blob));
    const click = spyOn(HTMLAnchorElement.prototype, 'click');

    component.downloadFile();

    expect(download).toHaveBeenCalledWith('files/doc.pdf');
    expect(click).toHaveBeenCalled();
  });

  it('warns when there is no way to download', () => {
    fixture.componentRef.setInput('download', null);
    const alert = spyOn(window, 'alert');

    component.downloadFile();

    expect(alert).toHaveBeenCalledWith('No callback');
  });
});

describe('EditableUploadComponent in a disabled form', () => {
  afterEach(() => TestBed.resetTestingModule());

  it('does not open the file dialog', () => {
    const dialog = { open: jasmine.createSpy('open') };
    TestBed.configureTestingModule({
      imports: [EditableUploadComponent, ReactiveFormsModule, TranslocoTestingModule.forRoot({ langs: { en: {} } })],
      providers: [provideHttpClient(), provideHttpClientTesting(), { provide: MatDialog, useValue: dialog }],
    });
    TestBed.overrideProvider(MatDialog, { useValue: dialog });
    TestBed.overrideTemplate(EditableUploadComponent, '<ng-template #fileDialog></ng-template>');
    const fixture = TestBed.createComponent(EditableUploadComponent);
    fixture.componentRef.setInput('upload', () => of());
    fixture.componentRef.setInput('download', () => null);
    fixture.detectChanges();
    const component = fixture.componentInstance as any;
    component.control = new FormControl({ value: null, disabled: true });

    component.selectFile();

    expect(dialog.open).not.toHaveBeenCalled();
  });
});
